create table if not exists public.skills (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, level public.content_level not null, difficulty integer not null default 1 check (difficulty between 1 and 5), created_at timestamptz not null default now());
create table if not exists public.lesson_sections (id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.lessons(id) on delete cascade, title text not null, order_index integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.lesson_blocks (id uuid primary key default gen_random_uuid(), section_id uuid not null references public.lesson_sections(id) on delete cascade, block_type text not null check (block_type in ('paragraph','heading','formula','example','warning','tip','table','diagram','interactive_question','quiz','summary','video')), content jsonb not null default '{}'::jsonb, order_index integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.lesson_skills (lesson_id uuid not null references public.lessons(id) on delete cascade, skill_id uuid not null references public.skills(id) on delete cascade, primary key (lesson_id, skill_id));
create table if not exists public.question_skills (question_id uuid not null references public.questions(id) on delete cascade, skill_id uuid not null references public.skills(id) on delete cascade, weight numeric(5,2) not null default 1, primary key (question_id, skill_id));
create table if not exists public.skill_prerequisites (skill_id uuid not null references public.skills(id) on delete cascade, prerequisite_skill_id uuid not null references public.skills(id) on delete cascade, primary key (skill_id, prerequisite_skill_id), check (skill_id <> prerequisite_skill_id));
create table if not exists public.cke_requirements (id uuid primary key default gen_random_uuid(), code text not null unique, level public.content_level not null, title text not null, description text, source_url text, mapped_skill_id uuid references public.skills(id) on delete set null, coverage_status text not null default 'planned' check (coverage_status in ('planned','mapped','lesson_ready','assessed','published')));
create table if not exists public.learning_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, lesson_id uuid references public.lessons(id) on delete set null, skill_id uuid references public.skills(id) on delete set null, question_id uuid references public.questions(id) on delete set null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.lessons add column if not exists objectives jsonb not null default '[]'::jsonb;
alter table public.lessons add column if not exists prerequisites jsonb not null default '[]'::jsonb;
alter table public.lessons add column if not exists next_lesson_id uuid references public.lessons(id) on delete set null;
alter table public.lessons add column if not exists previous_lesson_id uuid references public.lessons(id) on delete set null;
alter table public.questions add column if not exists cke_requirement_code text;
create index if not exists lesson_sections_lesson_idx on public.lesson_sections(lesson_id, order_index);
create index if not exists lesson_blocks_section_idx on public.lesson_blocks(section_id, order_index);
create index if not exists learning_events_user_idx on public.learning_events(user_id, created_at desc);
alter table public.skills enable row level security; alter table public.lesson_sections enable row level security; alter table public.lesson_blocks enable row level security; alter table public.lesson_skills enable row level security; alter table public.question_skills enable row level security; alter table public.skill_prerequisites enable row level security; alter table public.cke_requirements enable row level security; alter table public.learning_events enable row level security;
drop policy if exists skills_read on public.skills; create policy skills_read on public.skills for select to authenticated using (true);
drop policy if exists lesson_sections_read on public.lesson_sections; create policy lesson_sections_read on public.lesson_sections for select to authenticated using (true);
drop policy if exists lesson_blocks_read on public.lesson_blocks; create policy lesson_blocks_read on public.lesson_blocks for select to authenticated using (true);
drop policy if exists lesson_skills_read on public.lesson_skills; create policy lesson_skills_read on public.lesson_skills for select to authenticated using (true);
drop policy if exists question_skills_read on public.question_skills; create policy question_skills_read on public.question_skills for select to authenticated using (true);
drop policy if exists prerequisites_read on public.skill_prerequisites; create policy prerequisites_read on public.skill_prerequisites for select to authenticated using (true);
drop policy if exists cke_read on public.cke_requirements; create policy cke_read on public.cke_requirements for select to authenticated using (true);
drop policy if exists events_own on public.learning_events; create policy events_own on public.learning_events for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
